INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('amex-platinum', 1, 'amex-platinum/equinox-credit', 10, 'Equinox Credit', 'Up to $300 per calendar year on Equinox club or Equinox+ digital membership.', 'wellness', 'barbell', 'Equinox', 30000, 'annual', 'calendar', NULL, true, NULL, NULL, '["Enroll in the benefit","Pay for an Equinox club or Equinox+ membership with the card"]', NULL);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('amex-platinum', 1, 'amex-platinum/clear-plus-credit', 11, 'CLEAR+ Credit', 'Up to $219 per calendar year toward a CLEAR+ membership.', 'travel', 'fingerprint', 'CLEAR', 21900, 'annual', 'calendar', NULL, false, NULL, NULL, '["Sign up for CLEAR+ and pay with the Platinum Card"]', NULL);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('amex-platinum', 1, 'amex-platinum/global-entry-tsa-precheck-credit', 12, 'Global Entry / TSA PreCheck Credit', 'Statement credit for Global Entry ($120) or TSA PreCheck (up to $85) application fee.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry or TSA PreCheck application fee with the Platinum Card"]', 'Global Entry ($120) every 4 years, or TSA PreCheck (up to $85) every 4.5 years, counted from your last credit.');
