INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('bofa-premium-rewards-elite', 1, 'bofa-premium-rewards-elite/airline-incidental-credit', 0, 'Airline Incidental Credit', 'Up to $300 per calendar year in statement credits for airline incidentals like seat upgrades, bag fees, lounge fees and in-flight services.', 'airline', 'airplane', NULL, 30000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Pay for qualifying airline incidentals (seat upgrades, bags, lounge fees, in-flight) with the card","Statement credit posts automatically"]', 'No need to pick an airline. Airfare itself usually doesn''t count.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('bofa-premium-rewards-elite', 1, 'bofa-premium-rewards-elite/lifestyle-credit', 1, 'Lifestyle Credit', 'Up to $150 per calendar year in statement credits for streaming, food delivery, fitness subscriptions and rideshare.', 'other', 'sparkle', NULL, 15000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Pay qualifying merchants (e.g. Netflix, Hulu, DoorDash, Uber, Lyft, Peloton) with the card","Statement credit posts in about 2-3 weeks"]', 'Eligibility depends on how the merchant is categorized, so some services (Spotify and Instacart, for example) may not trigger it.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('bofa-premium-rewards-elite', 1, 'bofa-premium-rewards-elite/global-entry-tsa-precheck-credit', 2, 'Global Entry / TSA PreCheck Credit', 'Up to $120 in statement credits for a Global Entry or TSA PreCheck application fee.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry or TSA PreCheck application fee with the card","Statement credit posts automatically"]', 'Once every four years.');
