INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('capital-one-venture-x', 1, 'capital-one-venture-x/capital-one-travel-credit', 0, 'Capital One Travel Credit', '$300 annual credit for bookings made through Capital One Travel, applied at checkout.', 'travel', 'suitcase', 'Capital One Travel', 30000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Book flights, hotels, or rental cars through Capital One Travel with the Venture X card.","Select the travel credit at checkout; it can be split across multiple purchases.","Use before the next account-open anniversary, when unused credit expires."]', 'Applied at checkout rather than as a statement credit. You don''t earn miles on the part the credit covers, and it''s restored if you cancel a refundable booking before it expires.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('capital-one-venture-x', 1, 'capital-one-venture-x/global-entry-tsa-precheck-credit', 1, 'Global Entry / TSA PreCheck Credit', 'Statement credit up to $120 for a Global Entry or TSA PreCheck application fee, once every four years.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry or TSA PreCheck application fee with the Venture X card.","Statement credit posts automatically."]', 'Once every 4 years.');
