INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-ihg-one-rewards-premier', 1, 'chase-ihg-one-rewards-premier/united-travelbank-cash', 0, 'United TravelBank Cash', '$25 in United TravelBank cash twice a year (up to $50 per calendar year) after registering the card with MileagePlus.', 'airline', 'airplane', 'United', 2500, 'semiannual', 'calendar', NULL, true, NULL, NULL, '["Register the IHG Premier card with your MileagePlus account (Chase/United registration page).","Receive $25 TravelBank cash deposits around January 5 and July 5.","Apply TravelBank cash when booking on united.com or the United app."]', 'Deposited around January 5 and July 5. Each deposit may expire at the end of its six-month window.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-ihg-one-rewards-premier', 1, 'chase-ihg-one-rewards-premier/20k-spend-statement-credit', 1, '$20K Spend Statement Credit', '$100 statement credit (plus 10,000 bonus points) in each calendar year you spend $20,000 on the card.', 'other', 'tag', NULL, 10000, 'annual', 'calendar', NULL, false, 2000000, NULL, '["Spend at least $20,000 on purchases in a calendar year.","The $100 statement credit and 10,000 bonus points post automatically."]', 'Only earned after $20,000 of purchases in a calendar year.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-ihg-one-rewards-premier', 1, 'chase-ihg-one-rewards-premier/global-entry-tsa-precheck-nexus-credit', 2, 'Global Entry / TSA PreCheck / NEXUS Credit', 'Statement credit up to $120 for a Global Entry, TSA PreCheck, or NEXUS application fee once every four years.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the application fee with the IHG Premier card.","Statement credit posts automatically (one every four years)."]', 'Once every 4 years.');
INSERT INTO card_templates (id) VALUES ('chase-sapphire-preferred');
INSERT INTO template_versions (template_id, version, effective_from, status, issuer, product, network, kind, annual_fee_cents) VALUES ('chase-sapphire-preferred', 1, '2000-01-01', 'draft', 'Chase', 'Sapphire Preferred', 'visa', 'personal', 9500);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-preferred', 1, 'chase-sapphire-preferred/chase-travel-hotel-credit', 0, 'Chase Travel Hotel Credit', 'Up to $100 in statement credits each account anniversary year on hotel stays booked through Chase Travel.', 'lodging', 'bed', 'Chase Travel', 10000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Book a hotel stay through Chase Travel (chase.com or the Chase app).","Pay with the Sapphire Preferred card; the statement credit posts automatically up to $100 per anniversary year."]', 'Raised from $50 to $100 on June 15, 2026. For bookings made from that date, the credit is taken back if you cancel.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-preferred', 1, 'chase-sapphire-preferred/doordash-non-restaurant-monthly-promo', 1, 'DoorDash Non-Restaurant Monthly Promo', 'Up to $10 off one non-restaurant DoorDash order (grocery, convenience, retail) each calendar month for cardmembers with the complimentary DashPass.', 'shopping', 'moped', 'DoorDash', 1000, 'monthly', 'calendar', NULL, true, NULL, NULL, '["Activate the complimentary DashPass with the Sapphire Preferred card (activation deadline 12/31/2027).","Each month, place one qualifying non-restaurant DoorDash order paid with the card.","Select the $10 discount from the DoorDash promotion wallet at checkout."]', 'A discount in the DoorDash app, not a statement credit. One use a month; unused value doesn''t roll over. A $20 minimum order may apply.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-preferred', 1, 'chase-sapphire-preferred/global-entry-tsa-precheck-nexus-credit', 2, 'Global Entry / TSA PreCheck / NEXUS Credit', 'Statement credit up to $120 for a Global Entry, TSA PreCheck, or NEXUS application fee once every four years.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry, TSA PreCheck, or NEXUS application fee with the Sapphire Preferred card.","Statement credit posts automatically (one credit every four years)."]', 'Added June 15, 2026. Once every 4 years, counted from your last credit.');
INSERT INTO card_templates (id) VALUES ('chase-sapphire-reserve');
INSERT INTO template_versions (template_id, version, effective_from, status, issuer, product, network, kind, annual_fee_cents) VALUES ('chase-sapphire-reserve', 1, '2000-01-01', 'draft', 'Chase', 'Sapphire Reserve', 'visa', 'personal', 79500);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/annual-travel-credit', 0, 'Annual Travel Credit', 'Up to $300 in statement credits for travel purchases each account anniversary year.', 'travel', 'suitcase', NULL, 30000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Charge any travel purchase to the card","Statement credits post automatically until $300 is reached for the account anniversary year"]', 'Covers a broad range of travel and applies automatically.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/the-edit-hotel-credit', 1, 'The Edit Hotel Credit', 'Up to $250 back on each prepaid The Edit booking via Chase Travel (2-night minimum), up to $500 per calendar year.', 'lodging', 'bed', 'The Edit', 50000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Book a prepaid stay of at least 2 nights at a property in The Edit through Chase Travel","Pay with the Sapphire Reserve card","Receive up to $250 statement credit per booking, maximum two bookings/$500 per calendar year"]', 'Since 2026 the two $250 credits can be used any time in the calendar year (they used to be split by half-year). Each booking is capped at $250, so the full $500 takes two separate prepaid bookings.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/dining-credit-sapphire-reserve-exclusive-tables', 2, 'Dining Credit (Sapphire Reserve Exclusive Tables)', 'Up to $150 back for dining at Sapphire Reserve Exclusive Tables restaurants on OpenTable, January through June.', 'dining', 'fork-knife', 'OpenTable', 15000, 'semiannual', 'calendar', NULL, true, NULL, NULL, '["Link/enroll the card with OpenTable to access Sapphire Reserve Exclusive Tables","Dine at a participating Exclusive Tables restaurant and pay with the card","Statement credit posts, typically within days (up to about 4 weeks)"]', 'Unused amount does not carry into the second half.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/stubhub-viagogo-credit', 3, 'StubHub / viagogo Credit', 'Up to $150 back on StubHub and viagogo purchases, January through June.', 'entertainment', 'ticket', 'StubHub', 15000, 'semiannual', 'calendar', NULL, true, NULL, '2027-12-31', '["Activate the benefit once on Chase.com or the Chase Mobile app","Buy tickets on StubHub or viagogo with the card","Statement credit posts automatically"]', 'Benefit available through 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/doordash-restaurant-promo', 4, 'DoorDash Restaurant Promo', '$5 off one qualifying DoorDash restaurant order each calendar month.', 'dining', 'moped', 'DoorDash', 500, 'monthly', 'calendar', NULL, true, NULL, '2027-12-31', '["Activate complimentary DashPass with the Sapphire Reserve card (by 12/31/2027)","Pay with the card on a qualifying DoorDash restaurant order","Discount applies at checkout"]', 'A discount in the DoorDash app, not a statement credit. Part of a $25 monthly DoorDash package: this $5 plus two $10 non-restaurant promos. Available through 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/doordash-non-restaurant-promos', 5, 'DoorDash Non-Restaurant Promos', 'Two $10-off discounts each calendar month on non-restaurant (grocery, retail) DoorDash orders.', 'shopping', 'moped', 'DoorDash', 2000, 'monthly', 'calendar', NULL, true, NULL, '2027-12-31', '["Activate complimentary DashPass with the Sapphire Reserve card (by 12/31/2027)","Place a qualifying non-restaurant DoorDash order (grocery, retail) with the card","Each $10 discount applies at checkout; two per calendar month"]', 'Two separate $10 discounts, each on its own order. Available through 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/lyft-credit', 6, 'Lyft Credit', '$10 Lyft in-app credit each calendar month.', 'rideshare', 'car', 'Lyft', 1000, 'monthly', 'calendar', NULL, true, NULL, '2027-09-30', '["Add the Sapphire Reserve card as a payment method in the Lyft app","The $10 in-app credit is issued each calendar month and applied to rides"]', 'An in-app Lyft credit, not a statement credit. The card must be added in the Lyft app. Available through 9/30/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/peloton-membership-credit', 7, 'Peloton Membership Credit', 'Up to $10 in statement credits per month on eligible Peloton memberships.', 'wellness', 'bicycle', 'Peloton', 1000, 'monthly', 'calendar', NULL, true, NULL, '2027-12-31', '["Activate once at onepeloton.com/digital/promotions/chase","Pay for an eligible Peloton membership with the Sapphire Reserve card","Credit posts monthly, up to $10"]', 'Up to $120 a year. Available through 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-sapphire-reserve', 1, 'chase-sapphire-reserve/global-entry-tsa-precheck-nexus-fee-credit', 8, 'Global Entry / TSA PreCheck / NEXUS Fee Credit', 'One statement credit of up to $120 every four years for the application fee.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry, TSA PreCheck or NEXUS application fee with the card","Statement credit posts automatically"]', 'Once every 4 years, counted from your last credit.');
INSERT INTO card_templates (id) VALUES ('chase-united-quest');
INSERT INTO template_versions (template_id, version, effective_from, status, issuer, product, network, kind, annual_fee_cents) VALUES ('chase-united-quest', 1, '2000-01-01', 'draft', 'Chase', 'United Quest', 'visa', 'personal', 35000);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/united-travelbank-cash', 0, 'United TravelBank Cash', '$200 in United TravelBank cash after account opening and on each account anniversary, for United- or United Express-operated flights.', 'airline', 'airplane', 'United', 20000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["TravelBank cash is deposited automatically into the linked MileagePlus account after account opening and each anniversary.","Apply TravelBank cash at checkout when booking a United- or United Express-operated flight on united.com or the United app."]', 'Deposited as United TravelBank cash, not a statement credit. It may expire 12 months after deposit.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/renowned-hotels-and-resorts-credit', 1, 'Renowned Hotels and Resorts Credit', 'Up to $150 back each anniversary year on hotel stays prepaid through United''s Renowned Hotels and Resorts program.', 'lodging', 'bed', 'United Hotels', 15000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Book and prepay a stay directly through Renowned Hotels and Resorts with the United Quest card.","Statement credit posts up to $150 per anniversary year."]', NULL);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/jsx-credit', 2, 'JSX Credit', 'Up to $150 back as a statement credit each anniversary year on flights booked directly with JSX.', 'airline', 'airplane-tilt', 'JSX', 15000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Book JSX flights directly with JSX (jsx.com or app) using the United Quest card.","Statement credit posts up to $150 per anniversary year."]', NULL);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/avis-budget-rental-travelbank-credit', 3, 'Avis/Budget Rental TravelBank Credit', '$40 in United TravelBank cash for each of the first two Avis or Budget rentals per anniversary year (up to $80).', 'travel', 'car-profile', 'Avis Budget', 8000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Book an Avis or Budget rental through cars.united.com and pay with the United Quest card.","Receive $40 in United TravelBank cash for each of the 1st and 2nd rentals in the anniversary year."]', 'Paid as two $40 TravelBank deposits, one per rental, up to $80 a year. A 2-day minimum rental may apply.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/rideshare-credit-monthly-base', 4, 'Rideshare Credit (monthly base)', 'Up to $8 back each month on rideshare purchases after annual enrollment.', 'rideshare', 'car', NULL, 800, 'monthly', 'calendar', NULL, true, NULL, NULL, '["Enroll in the rideshare benefit via Chase (required each calendar year).","Pay for eligible rideshare with the United Quest card; up to $8 statement credit per month."]', '$100 a year: $8 a month plus $4 more in December. You must re-enroll each calendar year and credits start the month after, so do it early in January.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/rideshare-credit-december-top-up', 5, 'Rideshare Credit (December top-up)', 'Extra $4 rideshare credit in December (December cap is $12 vs. $8 in other months).', 'rideshare', 'car', NULL, 400, 'annual', 'calendar', NULL, true, NULL, NULL, '["Stay enrolled in the rideshare benefit for the calendar year.","In December, spend up to $12 on eligible rideshare with the card; the $4 above the $8 base comes from this entry."]', 'With the $8 monthly credit, $100 a calendar year.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/instacart-10-monthly-credit', 6, 'Instacart $10 Monthly Credit', '$10 Instacart credit on the first order each month for Instacart+ members paying with the card.', 'shopping', 'shopping-cart', 'Instacart', 1000, 'monthly', 'calendar', NULL, true, NULL, '2027-12-31', '["Register the United Quest card on Instacart''s Chase United page and activate the complimentary Instacart+ (3 months, then 50% off renewal).","Keep an active Instacart+ membership and set the card as payment or backup payment.","The $10 credit applies to the first order each month."]', 'Part of $180 a year in Instacart credits ($10 + $5 each month). Needs an active Instacart+ membership. Applied in Instacart, not as a statement credit. Ends 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/instacart-5-monthly-credit', 7, 'Instacart $5 Monthly Credit', '$5 Instacart credit on the second order each month for Instacart+ members paying with the card.', 'shopping', 'shopping-cart', 'Instacart', 500, 'monthly', 'calendar', NULL, true, NULL, '2027-12-31', '["Same setup as the $10 credit (registered card, active Instacart+).","The $5 credit applies to the second order each month."]', 'Needs an active Instacart+ membership. Ends 12/31/2027.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('chase-united-quest', 1, 'chase-united-quest/global-entry-tsa-precheck-nexus-credit', 8, 'Global Entry / TSA PreCheck / NEXUS Credit', 'Statement credit up to $120 for a Global Entry, TSA PreCheck, or NEXUS application fee once every four years.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the application fee with the United Quest card.","Statement credit posts automatically (one every four years)."]', 'Once every 4 years.');
INSERT INTO card_templates (id) VALUES ('citi-aadvantage-executive');
INSERT INTO template_versions (template_id, version, effective_from, status, issuer, product, network, kind, annual_fee_cents) VALUES ('citi-aadvantage-executive', 1, '2000-01-01', 'draft', 'Citi', 'AAdvantage Executive', 'mastercard', 'personal', 69500);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/lyft-credit', 0, 'Lyft Credit', '$15 Lyft credit after taking 3 eligible Lyft rides paid with the card in a calendar month (up to $180/yr).', 'rideshare', 'car', 'Lyft', 1500, 'monthly', 'calendar', NULL, true, NULL, NULL, '["Add the card as payment method in the Lyft app","Take 3 eligible rides paid with the card in a calendar month","Receive a $15 Lyft credit in the Lyft account (expires ~30 days after issue)"]', 'Raised from $10 to $15 a month on Aug 23, 2026. An in-app Lyft credit, not a statement credit; the card must be added in the Lyft app.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/avis-budget-car-rental-credit', 1, 'Avis / Budget Car Rental Credit', 'Up to $120 back per calendar year on eligible prepaid Avis or Budget rentals booked directly.', 'travel', 'car-profile', 'Avis Budget', 12000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Book a prepaid rental directly on avis.com or budget.com","Pay with the card; statement credit posts afterward"]', 'Pay-later and third-party bookings (including aa.com/cars) don''t count.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/american-airlines-vacations-credit', 2, 'American Airlines Vacations Credit', 'Up to $250 back per half-year ($500/yr) on eligible American Airlines Vacations package purchases.', 'travel', 'island', 'American Airlines Vacations', 25000, 'semiannual', 'calendar', NULL, false, NULL, NULL, '["Book a package with 2+ components (e.g. flight + hotel) on aavacations.com","Pay with the card; statement credit posts automatically"]', 'New Aug 23, 2026. $250 for January–June and $250 for July–December; unused amounts don''t roll over.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/inflight-admirals-club-credit', 3, 'Inflight & Admirals Club Credit', 'Up to $100 back per calendar year on American Airlines inflight purchases and eligible Admirals Club purchases.', 'airline', 'airplane', 'American Airlines', 10000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Pay for AA inflight food/beverage/Wi-Fi or eligible Admirals Club purchases with the card","Statement credit posts automatically"]', 'New Aug 23, 2026. Replaces the 25% inflight food and drink savings, which existing cardmembers keep through Sep 30, 2026.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/grubhub-credit-existing-cardmembers-only', 4, 'Grubhub Credit (existing cardmembers only)', 'Up to $10 per monthly billing statement on eligible Grubhub purchases; legacy benefit being phased out.', 'dining', 'hamburger', 'Grubhub', 1000, 'monthly', 'calendar', NULL, false, NULL, NULL, '["Pay for Grubhub orders with the card","Statement credit up to $10 per billing statement posts automatically"]', 'Not offered to new cardmembers from Aug 23, 2026; existing cardmembers keep it through Aug 31, 2027. Resets with each monthly statement rather than the calendar month.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-aadvantage-executive', 1, 'citi-aadvantage-executive/global-entry-tsa-precheck-credit', 5, 'Global Entry / TSA PreCheck Credit', 'Up to $120 statement credit for a Global Entry or TSA PreCheck application fee.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry or TSA PreCheck application fee with the card","Credit posts within 1-2 billing cycles"]', 'Once every 4 years.');
