INSERT INTO template_versions (template_id, version, effective_from, status, issuer, product, network, kind, annual_fee_cents) VALUES ('citi-strata-elite', 1, '2000-01-01', 'draft', 'Citi', 'Strata Elite', 'mastercard', 'personal', 59500);
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-strata-elite', 1, 'citi-strata-elite/hotel-benefit', 0, 'Hotel Benefit', 'Up to $300 off a hotel stay of 2+ nights booked through Citi Travel.', 'lodging', 'bed', 'Citi Travel', 30000, 'annual', 'calendar', NULL, false, NULL, NULL, '["Book a hotel stay of 2 or more nights on cititravel.com","Pay with the Strata Elite card; discount/credit applies to the booking"]', 'Minimum 2-night stay, booked through Citi Travel.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-strata-elite', 1, 'citi-strata-elite/splurge-credit', 1, 'Splurge Credit', 'Up to $200 in statement credits at up to 2 selected brands: 1stDibs, American Airlines, Best Buy, Future Personal Training, Live Nation.', 'shopping', 'shopping-bag', NULL, 20000, 'annual', 'calendar', NULL, true, NULL, NULL, '["Log in to Citi account and open the Splurge Credit dashboard","Click ''Select brand'' and choose up to 2 of the 5 eligible brands","Pay at the selected brand(s) with the card; credit posts within 1-2 billing cycles"]', 'Pick your brands before you buy; you can change them online or by phone. Some American Airlines and Live Nation purchases are excluded.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-strata-elite', 1, 'citi-strata-elite/blacklane-credit', 2, 'Blacklane Credit', 'Up to $100 per half-year ($200/yr) in statement credits for Blacklane chauffeur rides.', 'rideshare', 'car', 'Blacklane', 10000, 'semiannual', 'calendar', NULL, false, NULL, NULL, '["Book a Blacklane ride and pay with the Strata Elite card","Statement credit posts automatically (often at statement close)"]', '$100 for January–June and $100 for July–December. A ride counts toward the half-year in which it''s completed.');
INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('citi-strata-elite', 1, 'citi-strata-elite/global-entry-tsa-precheck-credit', 3, 'Global Entry / TSA PreCheck Credit', 'Up to $120 reimbursement for a Global Entry or TSA PreCheck application fee.', 'fee_credit', 'identification-card', 'Global Entry / TSA PreCheck', 12000, 'rolling', 'anniversary', 48, false, NULL, NULL, '["Pay the Global Entry or TSA PreCheck application fee with the card","Statement credit posts automatically"]', 'Once every 4 years.');
