INSERT INTO template_credits (template_id, version, credit_id, position, name, description, category, icon, merchant, value_cents, cadence, anchor, interval_months, enrollment_required, spend_threshold_cents, ends_on, redemption_steps, notes) VALUES ('wells-fargo-autograph-journey', 1, 'wells-fargo-autograph-journey/annual-airline-credit', 0, 'Annual Airline Credit', 'One-time $50 statement credit on the first airline purchase of at least $50 each card year.', 'airline', 'airplane', NULL, 5000, 'annual', 'anniversary', NULL, false, NULL, NULL, '["Make an airline purchase of $50 or more with the card (airline merchant category)","Credit posts within 60 days"]', 'The first year starts at account opening. After that, each year starts on the first day of the month after the annual fee posts (fee on Nov 10, year starts Dec 1).');
